public class DataTypes {
    public static void main(String[] args) {
        int     age    = 20;
        double  gpa    = 4.10;
        boolean passed = true;
        char    grade  = 'A';

        System.out.println("Age: "    + age);
        System.out.println("GPA: "    + gpa);
        System.out.println("Passed: " + passed);
