}

public class Student {
    private String name;
    private int    age;
    private double gpa;

    public Student(String name, int age, double gpa) {
        this.name = name;
        this.age  = age;
        this.gpa  = gpa;
    }

    public String getName() { return name; }

    public void setGpa(double gpa) {
        if (gpa >= 0 && gpa <= 5) this.gpa = gpa;
    }

    public void introduce() {
        System.out.println("Hi! I am " + name +
            ", age " + age + ", GPA: " + gpa);
    }

    public static void main(String[] args) {
        Student s1 = new Student("Alice", 20, 4.10);
        Student s2 = new Student("Bob",   22, 3.85);
        s1.introduce();
        s2.introduce();
        s1.setGpa(4.50);
    }
}

public class ControlFlow {
    public static void main(String[] args) {
        int score = 75;
        if      (score >= 80) System.out.println("Distinction");
        else if (score >= 70) System.out.println("Credit");
        else if (score >= 60) System.out.println("Pass");
        else                  System.out.println("Fail");

        int[] marks = {78, 85, 92, 67, 90};
        int total = 0;
        for (int i = 0; i < marks.length; i++) {
            total += marks[i];
        }
        System.out.println("Average: " + (total / marks.length));

        for (int m : marks) System.out.print(m + " ");
        System.out.println();

        char grade = 'B';
        switch (grade) {
            case 'A': System.out.println("Excellent!"); break;
            case 'B': System.out.println("Good job!");  break;
            default:  System.out.println("Keep going!");
        }
    }
}

interface Speakable {
    void speak();
    default void greet() {
        System.out.println("Hello from a speaking creature!");
    }
}

class Animal {
    protected String name;
    Animal(String name) { this.name = name; }
    public void eat() { System.out.println(name + " is eating."); }
}

class Dog extends Animal implements Speakable {
    Dog(String name) { super(name); }
    @Override
    public void speak() { System.out.println(name + ": Woof! 🐕"); }
}

class Cat extends Animal implements Speakable {
    Cat(String name) { super(name); }
    @Override
    public void speak() { System.out.println(name + ": Meow! 🐈"); }
}

public class Main {
    public static void main(String[] args) {
        Animal[] zoo = { new Dog("Rex"), new Cat("Kitty"), new Dog("Buddy") };
        for (Animal a : zoo) {
            a.eat();
            ((Speakable) a).speak();
        }
    }
}

import javax.swing.*;
import java.awt.*;

public class StudentForm extends JFrame {
    private JTextField nameField = new JTextField(16);
    private JTextField gpaField  = new JTextField(6);
    private JLabel     result    = new JLabel("Enter details above");

    public StudentForm() {
        setTitle("TDIT 214 — Student Entry");
        setSize(360, 200);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setLayout(new FlowLayout(FlowLayout.LEFT, 12, 12));

        add(new JLabel("Name:")); add(nameField);
        add(new JLabel("GPA:"));  add(gpaField);

        JButton btn = new JButton("Submit");
        btn.addActionListener(e -> {
            String name = nameField.getText();
            double gpa  = Double.parseDouble(gpaField.getText());
            result.setText(name + " — GPA: " + gpa +
                (gpa >= 4.0 ? " ✅ Dean's List!" : " 📚 Keep going!"));
        });

        add(btn); add(result);
        setVisible(true);
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(StudentForm::new);
    }
}
